import{_ as t,a}from"./chunks/ugso_whatsapp_action.BaaafHGF.js";import{_ as o,o as r,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const n="/assets/callmebot/en.png",l="/assets/callmebot/profiles-en.png",k=JSON.parse('{"title":"CallMeBot Whatsapp","description":"WhatsApp text messages from Home Assistant with recipient profiles and Blockly.","frontmatter":{"title":"CallMeBot Whatsapp","description":"WhatsApp text messages from Home Assistant with recipient profiles and Blockly."},"headers":[],"relativePath":"en/projects/callmebot/index.md","filePath":"en/projects/callmebot/index.md","lastUpdated":1793198184000}'),p={name:"en/projects/callmebot/index.md"};function c(d,e,h,m,u,f){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="callmebot-whatsapp" tabindex="-1">CallMeBot Whatsapp <a class="header-anchor" href="#callmebot-whatsapp" aria-label="Permalink to &quot;CallMeBot Whatsapp&quot;">​</a></h1><p>Since 0.1.5 the app is named <strong>CallMeBot Whatsapp</strong>. Existing profiles, MQTT topics and entity IDs are preserved. The separate <a href="./../callmebot-signal/">CallMeBot Signal</a> uses its own profiles and keys.</p><p>Beta <strong>HA App 0.1.6</strong> in the <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot" target="_blank" rel="noreferrer">same repository as Blocks for HA</a>. Complete <strong>DE/EN/FR</strong> interface and blocks, system language and light/dark/system appearance. Inspired by <a href="https://github.com/ioBroker/ioBroker.whatsapp-cmb" target="_blank" rel="noreferrer">ioBroker.whatsapp-cmb</a>; original UGSo implementation without ioBroker.</p><p><strong>Fix in 0.1.1:</strong> Sending works without <code>crypto.randomUUID</code>, including HTTP Ingress. Restart the app and reload the page after updating. Request IDs use random bytes when available or a timestamp/counter fallback; they deduplicate requests and are not authentication tokens.</p><p><img src="'+n+'" alt="English CallMeBot interface"></p><h2 id="installation-and-setup" tabindex="-1">Installation and setup <a class="header-anchor" href="#installation-and-setup" aria-label="Permalink to &quot;Installation and setup&quot;">​</a></h2><ol><li>Add <code>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</code> to the HA App Store.</li><li>Install <strong>CallMeBot Whatsapp</strong>, configure the MQTT broker and start the app.</li><li>Open the Ingress UI. Supervisor MQTT credentials take priority; app options are the fallback.</li><li>Activate your own recipient using the current bot number from the <a href="https://www.callmebot.com/blog/free-api-whatsapp-messages/" target="_blank" rel="noreferrer">official activation guide</a>. Send exactly <code>I allow callmebot to send me messages</code>.</li><li>Save a profile ID, name, activated phone number <strong>with + and country code</strong>, and its matching API key. Select a default. Up to 16 profiles.</li><li>The test button really sends to the selected saved profile; an empty selection uses the default.</li></ol><p>A blank key field preserves the stored key. Keys are never returned to the UI. They remain in <code>/data/profiles.json</code>, outside Blockly, MQTT messages, browser storage and logs. This backend file is not encrypted and is included in HA backups.</p><h2 id="callmebot-blockly-block" tabindex="-1">CallMeBot Blockly block <a class="header-anchor" href="#callmebot-blockly-block" aria-label="Permalink to &quot;CallMeBot Blockly block&quot;">​</a></h2><h3 id="select-saved-profiles" tabindex="-1">Select saved profiles <a class="header-anchor" href="#select-saved-profiles" aria-label="Permalink to &quot;Select saved profiles&quot;">​</a></h3><p>With <strong>CallMeBot 0.1.2 and Blocks for HA 0.1.69</strong>, the profile field opens a searchable list of names, IDs and the default recipient. <strong>Refresh</strong> reloads the list. The block displays the name while projects and YAML retain the original ID. An empty ID uses the current default recipient.</p><p><img src="'+l+'" alt="English CallMeBot profile picker"></p><p>Update/restart both apps and reload Blocks. HA must connect to the broker and enable MQTT discovery with the standard <code>homeassistant</code> prefix. CallMeBot discovers a diagnostic sensor, normally <code>sensor.ugso_callmebot_profiles</code>; Blocks reads its catalog through the existing HA connection. Renaming this sensor is supported because its catalog marker identifies it. Technical basis: <a href="https://www.home-assistant.io/integrations/sensor.mqtt/" target="_blank" rel="noreferrer">HA MQTT sensors and JSON attributes</a>.</p><p>The retained <code>ugso/callmebot/profiles</code> catalog contains IDs, names, default profile, count and a marker only. No phone numbers, messages or API keys are published. Changes and MQTT reconnections refresh it. Profile names are visible in MQTT and HA.</p><p>If the app, MQTT, discovery or HA connection is unavailable, manual IDs and the default recipient remain usable. Deleted IDs are never silently replaced in projects; the app rejects sending to a missing profile.</p><p>Since <strong>Blocks for HA 0.1.68</strong>, under <strong>Messages → WhatsApp · CallMeBot</strong>.</p><p><img src="'+t+'" alt="CallMeBot block"></p><p>Enter a profile ID or leave it empty for the default. Connect text, a variable or Jinja as the message. Logging: errors only, none or info. Exports native <code>mqtt.publish</code>, serializing JSON after template evaluation so quotes and newlines remain valid.</p><p>HA requires MQTT. JSON projects preserve the dedicated block. YAML imports back as a general HA/MQTT action.</p><h2 id="alternative-existing-whatsapp-integration" tabindex="-1">Alternative: existing WhatsApp integration <a class="header-anchor" href="#alternative-existing-whatsapp-integration" aria-label="Permalink to &quot;Alternative: existing WhatsApp integration&quot;">​</a></h2><p><img src="'+a+'" alt="WhatsApp integration block"></p><p>The second block calls <a href="https://faserf.github.io/ha-whatsapp/services.html" target="_blank" rel="noreferrer">FaserF’s WhatsApp integration</a>. Configure its app URL and <strong>API token from the WhatsApp app</strong> once in the HA setup dialog. The integration manages this token; the block does not need it.</p><p>Select <code>whatsapp.send_message · number</code> for the older format, <code>whatsapp.send_message · target</code> for the current documentation, or <code>notify.whatsapp</code> if configured. Recipient: <strong>country code without +</strong>. Message: text/Jinja. The optional account is exported for <code>whatsapp.send_message</code> only. Matching YAML imports as the dedicated block; extra options remain in the general HA action.</p><p>This alternative requires neither the CallMeBot app nor a CallMeBot key. The existing integration handles installation and WhatsApp connectivity.</p><h2 id="mqtt-protocol-and-limits" tabindex="-1">MQTT protocol and limits <a class="header-anchor" href="#mqtt-protocol-and-limits" aria-label="Permalink to &quot;MQTT protocol and limits&quot;">​</a></h2><ul><li>Send: <code>ugso/callmebot/send</code>, QoS 0, <strong>retain false</strong>.</li><li>Payload: <code>{&quot;profile&quot;:&quot;default&quot;,&quot;message&quot;:&quot;Hello from HA&quot;,&quot;loglevel&quot;:&quot;errors&quot;}</code>. Empty/omitted profile uses the default.</li><li>Optional <code>request_id</code>: one-hour deduplication per profile, keeping up to 1000 IDs.</li><li>Result: <code>ugso/callmebot/result</code>, non-retained profile, request ID, status and timestamp; no message or key.</li><li>Availability: <code>ugso/callmebot/availability</code>, retained <code>online</code>/<code>offline</code> for the broker connection.</li><li>Maximum 4000 characters, queue of 20, at least 10 seconds between attempts per profile. Faster commands are rejected, not delayed.</li><li>No automatic provider retries or replay after restart. Retained send commands are rejected.</li><li>One MQTT namespace/client ID: one app instance per broker. Restrict send-topic write permissions. The internal broker remains default; external MQTT with verified TLS is optional.</li></ul><p>CallMeBot Free is for personal texts to your own activated numbers. No groups, media, replies or delivery confirmation. <code>accepted</code> confirms API acceptance only. Phone, key and text are transmitted over HTTPS to CallMeBot. Source: <a href="https://www.callmebot.com/blog/free-api-whatsapp-messages/" target="_blank" rel="noreferrer">CallMeBot activation and API</a>.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Docker build/start, mock-provider backend tests, MQTT protocol, DE/EN/FR UI, mobile layout and Blockly export were checked. Real WhatsApp delivery and HA Supervisor installation still require verification with your own setup. No real messages were sent.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/callmebot" target="_blank" rel="noreferrer">Source and local test commands</a> · Apache-2.0 · Independent community project.</p><h2 id="beta-history-profile-backup-and-mqtt-tls" tabindex="-1">Beta: history, profile backup and MQTT TLS <a class="header-anchor" href="#beta-history-profile-backup-and-mqtt-tls" aria-label="Permalink to &quot;Beta: history, profile backup and MQTT TLS&quot;">​</a></h2><p>History persists up to 200 entries with timestamp, profile ID, source and result. Filter by profile/error status and explicitly confirm clearing. It contains no messages, numbers, API keys or request IDs. Accepted still means provider acceptance, not confirmed delivery. A storage error never causes automatic resending.</p><p>Profile backups encrypt numbers, API keys and the default profile using AES-GCM and a password-derived key (scrypt). Choose at least 12 characters and keep the password separately; it is not stored. Restoration requires it, explicit confirmation and valid authenticated content. Wrong passwords, damaged files or backups from the other CallMeBot app leave profiles untouched. Pending sends block restoration. MQTT credentials and history are excluded; use a full HA app backup for those.</p><p>Automatic HA broker selection remains the existing default. Disable it to configure an external host, port, username and password. TLS always checks certificates and hostname; custom PEM CA and client certificate/key uploads are supported. Choose the broker TLS port, often 8883. Empty secret fields preserve saved values. HA/Blocks must use this broker or forward send/result/profile/discovery topics between brokers; this is not an automatic broker bridge.</p><p>Existing profiles.json, recipient keys, MQTT topics and entity IDs remain unchanged. History uses /data/history.json; explicitly saved MQTT settings use /data/mqtt.json. No automatic configuration rewrite. All new UI labels support DE/EN/FR.</p><p>Beta is displayed in the UI and description. HA has no native beta stage, so the valid experimental configuration stage remains. <a href="https://developers.home-assistant.io/docs/apps/configuration/" target="_blank" rel="noreferrer">HA configuration</a>.</p>',36)])])}const y=o(p,[["render",c]]);export{k as __pageData,y as default};
